    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configure los ajustes de todo el sistema: URL base, seguridad, idioma predeterminado, zona horaria, valores predeterminados de puntuación de riesgo y más.',
    'SettingsPreferencesDesc'             => 'Valores predeterminados y preferencias de comportamiento en SimpleRisk: idioma, zona horaria, estados de auditoría, requisitos de mapeo de riesgos, opciones para alternar el comportamiento de la interfaz de usuario, etc.',
    'SettingsFileUploadDesc'              => 'Tipos de archivo permitidos para subir y límites de tamaño para los distintos campos de adjuntos.',
    'SettingsMailDesc'                    => 'Configuración SMTP para notificaciones de correo electrónico salientes, incluyendo transporte, host, autenticación y dirección de respuesta.',
    'SettingsBackupsDesc'                 => 'Configure la retención, la programación y los enlaces de descarga de las copias de seguridad de la base de datos de SimpleRisk.',
    'SettingsSecurityDesc'                => 'Autenticación, sesión, política de contraseñas, URL base y configuración de seguridad de la API.',
    'SettingsLoggingDesc'                 => 'Configuración del registro de depuración y auditoría: niveles de registro, retención y ubicación de los archivos de registro.',
    'HealthCheckDesc'                     => 'Diagnóstico del estado del sistema: versión de PHP, extensiones, permisos de archivos, conectividad de la base de datos, programación de tareas cron y activaciones de Extras.',
    'AnnouncementsDesc'                   => 'Redacte y gestione los anuncios en banner visibles para todos los usuarios.',
    'RegisterAndUpgradeDesc'              => 'Registre su instalación de SimpleRisk, introduzca o renueve una clave de suscripción y lance actualizaciones del Core y de los Extras con un solo clic.',
    'QueueMonitorDesc'                    => 'Inspeccione la cola de trabajos en segundo plano: trabajos pendientes, en curso y fallidos.',
    'ExtrasDesc'                          => 'Active, desactive y configure los Extras de SimpleRisk (complementos de pago).',
    'ArtificialIntelligenceExtraDesc'     => 'El Extra de Inteligencia Artificial proporciona un análisis de riesgos mejorado (incluidas evaluaciones FAIR) y documentación personalizada.',
    'CustomizationExtraDesc'              => 'El Extra de Personalización permite añadir y eliminar distintos tipos de campos y crear dinámicamente plantillas de página personalizadas.',
    'NotificationExtraDesc'               => 'El Extra de Notificaciones por correo electrónico permite a SimpleRisk enviar notificaciones por correo electrónico cuando los riesgos se registran, se modifican o se les aplica cualquier otra acción. Este Extra también se puede añadir como un script programado para enviar recordatorios periódicos cuando los riesgos están listos para una revisión de gestión. En el producto SimpleRisk Core, sin este Extra, no se comunica ninguna notificación fuera de la propia herramienta.',
    'VulnerabilityManagementExtraDesc'    => 'El módulo adicional de gestión de vulnerabilidades permite a los clientes integrar su instancia de SimpleRisk con Qualys, Tenable.io o Rapid7 Nexpose/InsightVM e importar datos de activos y vulnerabilidades a SimpleRisk. A partir de ahí, pueden seleccionar los sitios que desean cubrir, determinar qué puntuaciones de vulnerabilidad deben importarse y priorizar qué vulnerabilidades se convierten en riesgos para su seguimiento.',
    'IncidentManagementExtraDesc'         => 'El Extra de Gestión de Incidentes se basa en la Guía de manejo de incidentes de seguridad informática NIST 800-61 y proporciona capacidades de gestión de incidentes dentro del sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Cambie el nombre de la terminología de SimpleRisk (riesgo, activo, marco, etc.) en toda la interfaz.',
    'RiskConfigurationDesc'               => 'Configure las reglas de puntuación de riesgos: niveles, apetito de riesgo, umbrales de SLA y las fórmulas de riesgo clásica y de factores contribuyentes.',
    'RiskAndThreatCatalogDesc'            => 'Mantener actualizado el catálogo de valores de riesgo y amenaza utilizados en los menús desplegables.',
    'AddAndRemoveValuesDesc'              => 'Gestione los valores de las listas desplegables de los campos de riesgo: ubicación, origen, categoría, equipo, tecnología y más.',
    'AssetValuationDesc'                  => 'Configure la escala de valoración de activos y las anulaciones de valoración por activo.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Agregar, editar, deshabilitar y restablecer usuarios; administrar la política de contraseñas.',
    'RoleManagementDesc'                  => 'Defina los roles y los permisos que otorga cada rol.',
    'TeamManagementDesc'                  => 'Cree y gestione equipos utilizados para filtrar la visibilidad de los registros.',
    'SeparationExtraDesc'                 => 'El Extra de Separación basada en equipos restringe la visualización de riesgos únicamente a los usuarios que son miembros del equipo al que está asignado el riesgo. En el producto SimpleRisk Core, sin este Extra, todos los usuarios pueden ver todos los riesgos.',
    'CustomAuthenticationExtraDesc'       => 'El Extra de Autenticación personalizada ofrece soporte para la autenticación con Active Directory y SAML. En el producto SimpleRisk Core, sin este Extra, la única opción es crear nuevos usuarios en el repositorio de identidades de SimpleRisk.',
    'EncryptionExtraDesc'                 => 'La función adicional de base de datos cifrada genera una clave de cifrado AES-256 aleatoria y la utiliza para cifrar el texto confidencial antes de insertarlo en la base de datos de SimpleRisk. Esto impide que cualquier persona pueda ver o modificar los datos sin usar directamente la aplicación SimpleRisk.',
    'OrganizationManagementDesc'          => 'El Extra de Jerarquía organizativa permite definir varias unidades de negocio que pueden incluir cualquier número de equipos. Después, los usuarios se pueden asignar a uno o varios equipos de diversas unidades de negocio. Esto afecta a la capacidad de un usuario para ver y utilizar los equipos, usuarios y activos con los que no está asociado.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Elimine riesgos de forma masiva. Úselo con moderación: las eliminaciones son permanentes.',
    'AuditTrailDesc'                      => 'Busque y exporte el registro de auditoría del sistema con las acciones de los usuarios.',
    'ImportExportExtraDesc'               => 'El Extra de Importación-Exportación permite importar datos a SimpleRisk asignando los campos de un archivo CSV a los campos de la base de datos de SimpleRisk. Se puede utilizar para importar resultados de auditoría desde una hoja de cálculo de terceros, resultados de análisis de vulnerabilidades desde otra herramienta, activos desde su CMDB y más. El Extra también permite exportar desde SimpleRisk archivos CSV que contienen riesgos, mitigaciones, revisiones o un informe combinado de los tres.',
    'JiraExtraDesc'                       => 'El Extra de Integración con Jira permite a los usuarios integrarse de forma bidireccional con una instancia de Jira. Permite vincular riesgos con incidencias de Jira, así como sincronizar sus datos, estado y comentarios.',
    'APIExtraDesc'                        => 'El Extra de API permite a los clientes utilizar una API RESTful para crear interacciones mediante scripts con otras aplicaciones, logrando una automatización avanzada y aprovechando la infraestructura existente.',
    'AdvancedSearchExtraDesc'             => 'El Extra de Búsqueda avanzada convierte el cuadro de búsqueda de la barra superior en una única búsqueda en riesgos, marcos, controles, documentos, excepciones, pruebas, auditorías, activos y grupos de activos, con una página de búsqueda completa para trabajar con los resultados. Solo muestra los registros que el usuario tiene permiso para ver.',
    'AssessmentsExtraDesc'                => 'El Extra de Evaluación de riesgos permite a los usuarios definir contactos, crear preguntas (incluida su lógica), agrupar varias preguntas en una plantilla de cuestionario, crear cuestionarios y enviarlos a los contactos, ver los resultados de los cuestionarios, añadir riesgos basados en esos resultados, comparar los resultados a lo largo del tiempo, importar y exportar evaluaciones personalizadas externamente, y revisar el registro de auditoría de la evaluación de riesgos.',
    'ActiveAssessmentsDesc'               => 'Vea y gestione las evaluaciones actualmente en curso.',
    'WorkflowsExtraDesc'                  => 'El Extra de Flujos de trabajo proporciona un motor de flujos de trabajo visual y basado en eventos que automatiza las acciones de gestión de riesgos en respuesta a eventos dentro de SimpleRisk. Puede diseñar flujos de trabajo que se activen ante cambios (como que un riesgo se registre, se actualice o se revise) para encaminar aprobaciones, asignar tareas y mantener su proceso en marcha sin intervención manual.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'El Extra de Secure Controls Framework (SCF) es una integración directa entre el Secure Controls Framework y SimpleRisk. Importa el catálogo de controles del SCF y sus correspondencias con una amplia variedad de marcos de cumplimiento y ciberseguridad a la funcionalidad de Gobernanza de SimpleRisk, para que pueda adoptar los marcos que necesite y gestionar sus controles sin tener que crearlos manualmente.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migre las columnas de fecha de revisión de tipo varchar heredadas a tipos de fecha adecuados. Solo visible cuando sea necesario.',
    'DatabaseUpgradeDesc'                 => 'Active manualmente la rutina de actualización de la base de datos de SimpleRisk.',

    // Configure Hub - Extra labels (only the ones not already defined elsewhere in this file)
    'ArtificialIntelligenceExtra'         => 'Extra de Inteligencia Artificial',
    'NotificationExtra'                   => 'Extra de notificaciones',
    'TeamBasedSeparationExtra'            => 'Extra de Separación Basada en Equipos',
    'CustomAuthenticationExtra'           => 'Extra de Autenticación Personalizada',
