    // and a promise that included it would be false.
    'ApplicabilityAppliesToControlNotSelection' => 'Se registrará únicamente para "{$name}"; los {$n} controles que ha seleccionado no se verán afectados.',

    // Task 65: the VISIBLE label on the controls toolbar's SoA button. The full
