    'HowDoYouWantToAddAFramework' => '¿Cómo quieres añadir un marco?',
    'CreateFrameworkManually' => 'Crear uno manualmente',
    'CreateFrameworkManuallyHint' => 'Asigne usted mismo el nombre al marco y después añada o asigne sus controles.',
    // Named for the framework rather than for its vendor. The hint was reworded
