    'RestoreTemplateConfirmBodyRisk' => 'Esto restablece todos los campos de las pestañas Detalles, Mitigación y Revisión a sus valores predeterminados para este grupo de plantillas. Los demás grupos de plantillas no se ven afectados.',
    'RestoreTemplateConfirmBody' => 'Esto restablece todos los campos de esta plantilla a sus valores predeterminados para este grupo de plantillas. Los demás grupos de plantillas no se ven afectados.',
    // CVSS holder's collapsed Temporal/Environmental/Impact-Modifiers
    // accordion (buildCvssHolder(), risk-details-form.js) -- these three
    // groups are optional CVSS v2 refinements on top of the required Base
    // Score Metrics, so they collapse behind this header by default.
    'AdvancedMetrics' => 'Métricas avanzadas',
    // CVSS holder's Base Score Metrics sub-group headers (buildCvssHolder(),
    // risk-details-form.js) -- distinct from the existing 'ExploitabilityMetrics'/
    // 'ImpactMetrics' keys, which the legacy cvss_modal_content.php modal
    // still renders as plain "Exploitability Metrics"/"Impact Metrics" and
    // must keep unchanged. These fold the umbrella "Base Score Metrics"
    // heading into each sub-group's own header instead of a separate label.
    'BaseScoreExploitabilityMetrics' => 'Métricas de explotabilidad de la puntuación base',
    'BaseScoreImpactMetrics' => 'Métricas de impacto de la puntuación base',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Cómo se puede acceder a la vulnerabilidad.
• Local: requiere acceso local, como una consola o un shell.
• Red adyacente: el atacante debe estar en el mismo segmento de red físico o lógico.
• Red: se puede explotar de forma remota a través de una red, sin necesidad de acceso local ni adyacente.',
    "AttackComplexityHelp" => 'Qué complejo es el ataque una vez que el atacante tiene acceso al objetivo.
• Alta: requiere condiciones especializadas que son difíciles de preparar.
• Media: deben cumplirse algunas condiciones, pero la explotación no es difícil una vez cumplidas.
• Baja: no se necesitan condiciones especiales.',
    "AuthenticationHelp" => "Número de veces que un atacante debe autenticarse en el objetivo para explotarlo.\n• Múltiple: se requiere autenticación dos o más veces, incluso con las mismas credenciales.\n• Única: se requiere autenticación una sola vez.\n• Ninguna: no se requiere autenticación.",
    "ConfidentialityImpactHelp" => 'El impacto sobre la confidencialidad de los datos que procesa el sistema si se explota.
• Ninguno: sin impacto.
• Parcial: cierta divulgación de información, pero el atacante no controla cuál, o la pérdida es limitada.
• Completo: divulgación total de toda la información del sistema.',
    "IntegrityImpactHelp" => 'El impacto sobre la integridad del sistema si se explota.
• Ninguno: sin impacto.
• Parcial: se pueden modificar algunos datos, pero el atacante no controla cuáles, o el alcance es limitado.
• Completo: compromiso total de la integridad del sistema; el atacante puede modificar cualquier archivo.',
    "AvailabilityImpactHelp" => "Impacto en la disponibilidad del sistema si se explota.\n• Ninguno: ningún impacto.\n• Parcial: rendimiento reducido o interrupciones en la disponibilidad.\n• Completo: apagado total del recurso afectado.",
    "RemediationLevelHelp" => 'El nivel de remediación disponible para la vulnerabilidad.
• Corrección oficial: hay disponible una solución completa del proveedor.
• Corrección temporal: hay disponible una corrección oficial pero temporal.
• Solución alternativa: existe una solución alternativa no oficial y ajena al proveedor.
• No disponible: no hay ninguna solución disponible o no se puede aplicar ninguna.',
    "ReportConfidenceHelp" => 'El grado de confianza en la existencia de la vulnerabilidad y la credibilidad de sus detalles técnicos.
• No confirmado: un único informe de origen sin confirmar; el problema subyacente es especulativo.
• No corroborado: varias fuentes independientes informan del mismo comportamiento, pero la causa raíz no está confirmada.
• Confirmado: el proveedor ha reconocido el problema, o se ha confirmado mediante análisis del código fuente o del exploit.',
    "CollateralDamagePotentialHelp" => 'El potencial de pérdida de vidas, de activos físicos o de pérdidas económicas si se explota la vulnerabilidad.
• Ninguno: no es probable ninguna pérdida de este tipo.
• Bajo a medio: es posible una pérdida moderada.
• Alto: un impacto catastrófico en los activos, los ingresos o la seguridad de la organización.',
    "TargetDistributionHelp" => "La proporción de sistemas vulnerables en su entorno.\n• Ninguno: no existen sistemas objetivo.\n• Bajo: entre el 1 y el 25 % de los sistemas son vulnerables.\n• Medio: entre el 26 y el 75 % son vulnerables.\n• Alto: entre el 76 y el 100 % son vulnerables.",
    "ConfidentialityRequirementHelp" => 'Qué importancia tiene para su organización la confidencialidad del activo afectado.
• Baja: una pérdida de confidencialidad tiene un impacto limitado.
• Media: tiene un impacto grave.
• Alta: tiene un impacto catastrófico.',
    "IntegrityRequirementHelp" => 'Qué importancia tiene para su organización la integridad del activo afectado.
• Baja: una pérdida de integridad tiene un impacto limitado.
• Media: tiene un impacto grave.
• Alta: tiene un impacto catastrófico.',
    "AvailabilityRequirementHelp" => 'Qué importancia tiene para su organización la disponibilidad del activo afectado.
• Baja: una pérdida de disponibilidad tiene un impacto limitado.
• Media: tiene un impacto grave.
• Alta: tiene un impacto catastrófico.',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'Cómo tendría que llegar un atacante a esta vulnerabilidad y aprovecharla: dónde debe estar, qué complejidad tiene el ataque y si necesita autenticarse primero.',
    'BaseScoreImpactMetricsDescription' => 'Qué ocurre si la vulnerabilidad se explota con éxito: el efecto sobre la confidencialidad, la integridad y la disponibilidad del sistema afectado.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Cómo cambia con el tiempo la amenaza real que representa esta vulnerabilidad: el estado actual del código de explotación, las soluciones disponibles y el grado de certeza de los informes sobre su existencia.',
    'EnvironmentalScoreMetricsDescription' => 'Cómo depende el riesgo de esta vulnerabilidad de su entorno: el potencial de daño real y cuántos de sus sistemas resultan realmente afectados.',
    'ImpactSubscoreModifiersDescription' => 'Pondera el impacto de la puntuación base según la importancia real de la confidencialidad, la integridad y la disponibilidad para este activo concreto.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Si se produce un exploit de la amenaza, ¿cuánto daño se causará?
0 = Nada
5 = Los datos de un usuario individual se ven comprometidos o afectados.
10 = Destrucción completa del sistema o de los datos',
    'ReproducibilityHelp' => '¿Qué facilidad hay para reproducir el exploit de la amenaza?
0 = Muy difícil o imposible, incluso para los administradores de la aplicación.
5 = Se requieren uno o dos pasos; puede que sea necesario ser un usuario autorizado.
10 = Basta con un navegador web y la barra de direcciones, sin autenticación.',
    'ExploitabilityHelp' => '¿Qué se necesita para explotar esta amenaza?' . "\n" . '0 = Conocimientos avanzados de programación y redes, con herramientas de ataque personalizadas o avanzadas.' . "\n" . '5 = Existe malware en Internet, o se puede explotar fácilmente utilizando las herramientas de ataque disponibles.' . "\n" . '10 = Solo un navegador web',
    'AffectedUsersHelp' => '¿Cuántos usuarios se verán afectados?' . "\n" . '0 = Ninguno' . "\n" . '5 = Algunos usuarios, pero no todos' . "\n" . '10 = Todos los usuarios',
    'DiscoverabilityHelp' => '¿Qué facilidad hay para descubrir esta amenaza?
0 = Muy difícil o imposible; requiere código fuente o acceso administrativo.
