9 = Los detalles de fallos como este ya son de dominio público y se pueden descubrir fácilmente con un motor de búsqueda.
10 = La información es visible en la barra de direcciones del navegador web o en un formulario.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
