    'SkillLevelHelp' => '¿Qué nivel de conocimientos técnicos posee este grupo de agentes de amenazas?' . "\n" . '1 = Sin conocimientos técnicos' . "\n" . '3 = Algunas habilidades técnicas' . "\n" . '5 = Usuario avanzado de informática' . "\n" . '6 = Habilidades de redes y programación' . "\n" . '9 = Habilidades de penetración de seguridad',
    'MotiveHelp' => '¿Qué grado de motivación tiene este grupo de agentes de amenaza para encontrar y explotar esta vulnerabilidad?
1 = Recompensa baja o nula
4 = Recompensa posible
9 = Recompensa alta',
    'OpportunityHelp' => '¿Qué recursos y oportunidades necesita este grupo de agentes de amenaza para encontrar y explotar esta vulnerabilidad?
