    'AssetScoring' => 'Puntuación de activos',
    'AssetScoringSettingsHint' => 'Cada activo se califica como Bajo, Moderado o Alto en confidencialidad, integridad y disponibilidad, y la confidencialidad puede ser en cambio No aplicable, lo que la excluye de ambos resultados. Su categorización FIPS es la más alta de las tres calificaciones. Su puntuación ponderada es el promedio ponderado de los tres valores de nivel, y los umbrales de banda convierten esa puntuación en una banda Baja, Moderada o Alta. Cambiar esta configuración vuelve a puntuar todos los activos de inmediato.',
    'Weights' => 'Ponderaciones',
    'AssetScoringWeightsHint' => 'Cuánto cuenta cada objetivo en la puntuación ponderada: de 0 a 100, con hasta dos decimales. Una ponderación de 0 excluye ese objetivo. Integridad y Disponibilidad no pueden ser ambas 0, porque una confidencialidad No aplicable siempre se excluye.',
    'LevelValues' => 'Valores de nivel',
    'AssetScoringLevelValuesHint' => 'El número que aporta cada calificación a la puntuación ponderada: mayor que 0 y hasta 100, con hasta dos decimales, y Bajo menor que Moderado menor que Alto. Los valores predeterminados son Bajo 1, Moderado 2 y Alto 3.',
    'BandThresholds' => 'Umbrales de banda',
    'AssetScoringBandThresholdsHint' => 'Una puntuación ponderada igual o superior a un umbral se encuentra dentro de esa banda, y una puntuación inferior al umbral Moderado se considera Baja. El valor Moderado debe comenzar por encima del valor Bajo, y el valor Alto debe comenzar por encima del valor Moderado y no superar el valor Alto.',
    'ModerateStartsAt' => 'El nivel moderado comienza en',
    'HighStartsAt' => 'Alto comienza en',
    'DefaultScoringForNewAssets' => 'Puntuación predeterminada para nuevos activos',
    'AssetScoringDefaultsHint' => 'Preselecciona estas calificaciones cuando alguien añade un activo en el formulario de activos. Los activos creados mediante descubrimiento, importación o la API permanecen sin puntuar a menos que aporten sus propias calificaciones. Deje los tres en No establecido para desactivarlo.',
    'AssetScoringWeightsInvalid' => 'Los pesos de la puntuación de activos deben ser números del 0 al 100 con un máximo de dos decimales, y la integridad y la disponibilidad no pueden ser ambas iguales a 0.',
    'AssetScoringValuesInvalid' => 'Los valores del nivel de puntuación de activos deben ser números superiores a 0 y hasta 100 con un máximo de dos decimales, donde Bajo es inferior a Moderado y este a Alto.',
